"""Capitalize every word in a line of text."""

DEFAULT_SMALL_WORDS = frozenset({
    "a", "an", "and", "as", "at", "but", "by",
    "for", "in", "of", "on", "or", "the", "to", "with",
})


def titlecase(text, small_words=None):
    """Upper-case the first letter of every word and lower-case the rest.

    Words in ``small_words`` stay lowercase unless they are the first word.
    Pass ``small_words=None`` (default) to use ``DEFAULT_SMALL_WORDS``, or an
    explicit iterable to override.
    """
    small = DEFAULT_SMALL_WORDS if small_words is None else frozenset(
        w.lower() for w in small_words
    )
    words = text.split(" ")
    result = []
    first_content_seen = False
    for word in words:
        if word == "":
            result.append(word)
            continue
        lower = word.lower()
        if not first_content_seen or lower not in small:
            result.append(lower[:1].upper() + lower[1:])
            first_content_seen = True
        else:
            result.append(lower)
    return " ".join(result)

